-- Withdrawal processing modes and gateway attempt tracking.
alter table public.transactions
  add column if not exists processing_mode text not null default 'review',
  add column if not exists gateway_status text not null default 'not_attempted',
  add column if not exists gateway_reference text,
  add column if not exists gateway_attempts int not null default 0,
  add column if not exists gateway_error text,
  add column if not exists gateway_submitted_at timestamptz;
do $$ begin alter table public.transactions add constraint transactions_processing_mode_check check (processing_mode in ('gateway','review','manual')); exception when duplicate_object then null; end $$;
do $$ begin alter table public.transactions add constraint transactions_gateway_status_check check (gateway_status in ('not_attempted','submitted','failed')); exception when duplicate_object then null; end $$;
insert into public.settings (key,value) values ('withdrawal_mode','review') on conflict (key) do nothing;

create or replace function public.request_withdrawal(p_user uuid,p_amount numeric,p_card uuid)
returns uuid language plpgsql security definer set search_path=public as $$
declare w public.wallets%rowtype; c public.bank_accounts%rowtype; v_fee numeric; v_pct numeric; v_min numeric; v_max numeric; v_cap int; v_days text; v_start text; v_end text; v_tx uuid; v_used int; v_dow int; v_mins int; v_mode text;
begin
 select * into c from public.bank_accounts where id=p_card and user_id=p_user; if not found then raise exception 'Save a payout card before withdrawing.'; end if;
 if not exists(select 1 from public.leases where user_id=p_user and status='active') then raise exception 'You need at least one active lease to withdraw.'; end if;
 select coalesce(value::numeric,0) into v_min from public.settings where key='min_withdrawal'; select coalesce(value::numeric,0) into v_max from public.settings where key='max_withdrawal'; select coalesce(value::numeric,0) into v_pct from public.settings where key='withdrawal_fee'; select coalesce(value::int,1) into v_cap from public.settings where key='withdrawals_per_day'; select value into v_days from public.settings where key='withdrawal_days'; select value into v_start from public.settings where key='withdrawal_start'; select value into v_end from public.settings where key='withdrawal_end'; select case when value in('gateway','review','manual') then value else 'review' end into v_mode from public.settings where key='withdrawal_mode'; v_mode:=coalesce(v_mode,'review');
 if p_amount<v_min then raise exception 'Minimum withdrawal is %.',v_min; end if; if p_amount>v_max then raise exception 'Maximum withdrawal is %.',v_max; end if;
 select * into w from public.wallets where user_id=p_user for update; if p_amount>w.balance-w.locked then raise exception 'Insufficient available balance.'; end if;
 if exists(select 1 from public.transactions where user_id=p_user and type='withdrawal' and status='pending') then raise exception 'You already have a withdrawal awaiting review.'; end if;
 select count(*) into v_used from public.transactions where user_id=p_user and type='withdrawal' and status<>'rejected' and (created_at at time zone 'Africa/Lagos')::date=(now() at time zone 'Africa/Lagos')::date; if v_used>=v_cap then raise exception 'Daily limit reached — % withdrawals per day.',v_cap; end if;
 v_dow:=extract(dow from(now() at time zone 'Africa/Lagos'))::int; v_mins:=extract(hour from(now() at time zone 'Africa/Lagos'))::int*60+extract(minute from(now() at time zone 'Africa/Lagos'))::int;
 if position(v_dow::text in coalesce(v_days,''))=0 then raise exception 'Withdrawals are closed today. Allowed days: %.',v_days; end if; if v_mins<(split_part(v_start,':',1)::int*60+split_part(v_start,':',2)::int) or v_mins>=(split_part(v_end,':',1)::int*60+split_part(v_end,':',2)::int) then raise exception 'Withdrawals are closed. Window: % – % WAT.',v_start,v_end; end if;
 v_fee:=round(p_amount*v_pct/100,2); insert into public.transactions(user_id,type,amount,fee,net_amount,description,reference,status,bank_name,account_number,account_name,processing_mode) values(p_user,'withdrawal',p_amount,v_fee,p_amount-v_fee,'Withdrawal to '||c.bank_name,'WTH-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)),'pending',c.bank_name,c.account_number,c.account_name,v_mode) returning id into v_tx; update public.wallets set locked=locked+p_amount,updated_at=now() where user_id=p_user; return v_tx;
end $$;

create or replace function public.complete_gateway_withdrawal(p_tx uuid,p_admin uuid,p_gateway_reference text default null) returns void language plpgsql security definer set search_path=public as $$
declare t public.transactions%rowtype; begin select * into t from public.transactions where id=p_tx and type='withdrawal' for update; if not found then raise exception 'Withdrawal not found.'; end if; if t.status<>'pending' then raise exception 'This withdrawal has already been processed.'; end if; update public.transactions set status='completed',processed_by=p_admin,gateway_status='submitted',gateway_reference=coalesce(p_gateway_reference,gateway_reference),gateway_error=null,gateway_submitted_at=coalesce(gateway_submitted_at,now()) where id=p_tx; update public.wallets set balance=balance-t.amount,locked=greatest(0,locked-t.amount),updated_at=now() where user_id=t.user_id; update public.profiles set total_withdrawn=total_withdrawn+t.net_amount where id=t.user_id; insert into public.audit_log(actor,action,target,meta) values(p_admin,'gateway_withdrawal_completed',p_tx,jsonb_build_object('gross',t.amount,'net',t.net_amount,'gateway_reference',p_gateway_reference)); end $$;
create or replace function public.record_gateway_withdrawal_failure(p_tx uuid,p_error text) returns void language plpgsql security definer set search_path=public as $$ begin update public.transactions set gateway_status='failed',gateway_attempts=gateway_attempts+1,gateway_error=left(coalesce(p_error,'Gateway request failed.'),500) where id=p_tx and type='withdrawal' and status='pending'; if not found then raise exception 'Pending withdrawal not found.'; end if; end $$;
create or replace function public.record_gateway_withdrawal_submission(p_tx uuid,p_gateway_reference text) returns void language plpgsql security definer set search_path=public as $$ begin update public.transactions set gateway_status='submitted',gateway_attempts=gateway_attempts+1,gateway_reference=p_gateway_reference,gateway_error=null,gateway_submitted_at=now() where id=p_tx and type='withdrawal' and status='pending'; if not found then raise exception 'Pending withdrawal not found.'; end if; end $$;
revoke all on function public.request_withdrawal(uuid,numeric,uuid),public.complete_gateway_withdrawal(uuid,uuid,text),public.record_gateway_withdrawal_failure(uuid,text),public.record_gateway_withdrawal_submission(uuid,text) from public,anon,authenticated;
grant execute on function public.request_withdrawal(uuid,numeric,uuid),public.complete_gateway_withdrawal(uuid,uuid,text),public.record_gateway_withdrawal_failure(uuid,text),public.record_gateway_withdrawal_submission(uuid,text) to service_role;

drop policy if exists settings_public_read on public.settings; drop policy if exists settings_member_read on public.settings;
create policy settings_member_read on public.settings for select using(key in('min_deposit','max_deposit','min_withdrawal','max_withdrawal','withdrawal_fee','withdrawals_per_day','income_days','income_drop_days','welcome_bonus','checkin_bonus','streak_7','streak_14','streak_30','withdrawal_days','withdrawal_start','withdrawal_end','withdrawal_mode','deposit_bank_1_name','deposit_bank_1_account_number','deposit_bank_1_account_name','deposit_bank_2_name','deposit_bank_2_account_number','deposit_bank_2_account_name','bank_name','account_number','account_name','whatsapp_link','telegram_link','support_link','support_email'));
drop policy if exists profiles_self_update on public.profiles;
drop policy if exists tickets_self_all on public.support_tickets; drop policy if exists tickets_self_read on public.support_tickets; drop policy if exists tickets_self_insert on public.support_tickets;
create policy tickets_self_read on public.support_tickets for select using(auth.uid()=user_id);
create policy tickets_self_insert on public.support_tickets for insert with check(auth.uid()=user_id);
